<script setup lang="ts">import {Save} from 'lucide-vue-next';definePageMeta({layout:'admin',middleware:'admin-auth'});const form=reactive({name:'',email:'',avatarUrl:'',avatarFileId:''}),pending=ref(true),saving=ref(false),error=ref('');const {show}=useAdminToast();onMounted(async()=>{try{const r=await $fetch<any>('/api/admin/profile');Object.assign(form,{name:r.data.name,email:r.data.email,avatarUrl:r.avatarUrl||'',avatarFileId:r.avatarFileId||''})}catch(e:any){error.value=e.data?.statusMessage||'Profil gagal dimuat.'}finally{pending.value=false}});async function save(){saving.value=true;try{await $fetch('/api/admin/profile',{method:'PATCH',body:{...form,avatarUrl:form.avatarUrl||null,avatarFileId:form.avatarFileId||null}});show('Profil berhasil diperbarui.','success')}catch(e:any){show(e.data?.statusMessage||'Profil gagal diperbarui.','error')}finally{saving.value=false}}</script><template><div><PageHead title="Profil" subtitle="Account · Profil Admin"/><section class="mt-6 max-w-xl rounded-2xl border border-neutral-line bg-white p-6"><p v-if="error" class="mb-4 text-sm text-red-700">{{error}}</p><label class="block text-sm font-semibold">Nama<input v-model="form.name" class="mt-1 w-full rounded-xl border px-3 py-2"/></label><label class="mt-4 block text-sm font-semibold">Email<p class="mt-1 rounded-xl bg-neutral-soft px-3 py-2 text-sm font-normal">{{form.email}}</p></label><label class="mt-4 block text-sm font-semibold">Avatar URL (opsional)<input v-model="form.avatarUrl" class="mt-1 w-full rounded-xl border px-3 py-2"/></label><button class="mt-6 inline-flex items-center gap-2 rounded-full bg-sht-olive-dark px-4 py-2 text-sm font-semibold text-white" :disabled="saving" @click="save"><Save class="h-4 w-4"/>{{saving?'Menyimpan...':'Simpan Profil'}}</button></section></div></template>
